// 'Fix': delegating method added to every layer for every leaf
 class Order {
   constructor(private customer: Customer) {}
+  // pass-throughs added to satisfy 'no chains' rule
+  customerName()    { return this.customer.name(); }
+  customerEmail()   { return this.customer.email(); }
+  customerTier()    { return this.customer.tier(); }
+  customerCountry() { return this.customer.country(); }
+  customerPhone()   { return this.customer.phone(); }
 }

 // caller, 'fixed':
-const code = order.getCustomer().getAddress().getCountry().getCode();
+const code = order.customerCountry().getCode();  // still chains into the result!

 // a fluent query builder was also 'fixed' into temp vars:
-const rows = db.from('orders').where('paid').limit(20).run();
+const q1 = db.from('orders'); const q2 = q1.where('paid'); const q3 = q2.limit(20); const rows = q3.run();
